	function _extractDialogControlLastMessageId(data) {
		const root = data?.result || data || {};
		const messages = Array.isArray(root.messages) ? root.messages : [];
		const ids = messages
			.map(message => Number(message?.id || message?.ID))
			.filter(n => Number.isFinite(n) && n > 0);
		return ids.length ? Math.max(...ids) : 0;
	}

	async function _getDialogControlLastMessageId(dialogId) {
		const id = _normalizeDialogControlRestDialogId(dialogId) || normId(dialogId);
		if (!id) return 0;
		const data = await _callBxRestMethod('im.dialog.messages.get', { DIALOG_ID: id, LIMIT: 1 });
		return _extractDialogControlLastMessageId(data);
	}

	function _assertDialogControlRestSuccess(result, label = 'Bitrix REST') {
		if (result === false || result?.result === false) throw new Error(`${label} returned false`);
		return true;
	}

	function _isDialogControlLaterMeta(meta) {
		return !!(meta?.hasLater && !meta?.hasUnread && !meta?.hasMention);
	}

	function _isDialogControlReadMeta(meta) {
		return !!meta && !meta.hasLater && !meta.hasUnread && !meta.hasMention && !(Number(meta.unreadCount) > 0);
	}

	function _waitDialogControlBitrixDomState(dialogId, predicate, timeout = 3200) {
		const id = normId(dialogId);
		const started = Date.now();
		return new Promise(resolve => {
			const check = () => {
				const el = id ? findChatElementById(id) : null;
				if (!el) {
					resolve(true);
					return;
				}
				let meta = null;
				try { meta = getItemMeta(el); } catch {}
				if (predicate(meta)) {
					resolve(true);
					return;
				}
				if (Date.now() - started >= timeout) {
					resolve(false);
					return;
				}
				setTimeout(check, 160);
			};
			setTimeout(check, 120);
		});
	}

	function _normalizeBitrixPath(rawUrl) {
		const raw = String(rawUrl || '').trim();
		if (!raw) return '';
		try {
			const url = new URL(raw, window.location.origin);
			if (url.origin !== window.location.origin) return '';
			return `${url.pathname}${url.search}${url.hash}`;
		} catch { return ''; }
	}

	function _extractTaskIdFromTaskUrl(rawUrl) {
		const path = _normalizeBitrixPath(rawUrl) || String(rawUrl || '');
		const m = /\/tasks\/task\/view\/(\d+)(?:\/|[?#]|$)/i.exec(path);
		return m ? m[1] : '';
	}

	let _dialogCurrentBitrixUserId = '';
	let _dialogCurrentBitrixUserPromise = null;
	const _dialogCurrentBitrixUserMigratedIds = new Set();
	function _migrateDialogTimeSelfStorage(userId) {
		const id = String(userId || '').trim();
		if (!/^\d+$/.test(id) || _dialogCurrentBitrixUserMigratedIds.has(id)) return false;
		_dialogCurrentBitrixUserMigratedIds.add(id);
		let changed = false;
		try {
			const keys = Array.from({ length: localStorage.length }, (_, index) => localStorage.key(index)).filter(Boolean);
			for (const sourceKey of keys) {
				const isVisits = sourceKey.startsWith(`${_PENA_TIME_VISITS_KEY}.self.`);
				const isTracker = sourceKey === `${_PENA_TIME_TRACKER_KEY}.self`;
				const isDraft = sourceKey === `${_PENA_TIME_MANUAL_DRAFT_KEY}.self`;
				const isLease = sourceKey === `${_PENA_TIME_ACTIVITY_LEASE_KEY}.self`;
				if (!isVisits && !isTracker && !isDraft && !isLease) continue;
				const targetKey = sourceKey.replace(/\.self(?=\.|$)/, `.${id}`);
				const sourceRaw = localStorage.getItem(sourceKey);
				if (sourceRaw == null) continue;
				if (isLease) {
					// A lease belongs to the old page realm. Migrating it would block the
					// confirmed user namespace with an owner that can no longer heartbeat.
					localStorage.removeItem(sourceKey);
					changed = true;
					continue;
				}
				if (isVisits) {
					let sourceVisits = [];
					let targetVisits = [];
					try { sourceVisits = JSON.parse(sourceRaw || '[]'); } catch {}
					try { targetVisits = JSON.parse(localStorage.getItem(targetKey) || '[]'); } catch {}
					const merged = _PENA_TIME_CONTROL?.mergeVisitedTasks?.([
						...(Array.isArray(targetVisits) ? targetVisits : []),
						...(Array.isArray(sourceVisits) ? sourceVisits : [])
					]) || (Array.isArray(targetVisits) && targetVisits.length ? targetVisits : sourceVisits);
					localStorage.setItem(targetKey, JSON.stringify(Array.isArray(merged) ? merged : []));
				} else if (localStorage.getItem(targetKey) == null) {
					localStorage.setItem(targetKey, sourceRaw);
				}
				localStorage.removeItem(sourceKey);
				changed = true;
			}
		} catch {}
		return changed;
	}

	function _acceptCurrentBitrixUserId(rawId) {
		const id = String(rawId || '').trim();
		if (!/^\d+$/.test(id)) return '';
		_dialogCurrentBitrixUserId = id;
		_migrateDialogTimeSelfStorage(id);
		return id;
	}

	function _getCurrentBitrixUserId() {
		if (/^\d+$/.test(_dialogCurrentBitrixUserId)) return _dialogCurrentBitrixUserId;
		const topWin = _getSafeTopWindow();
		for (const BXNS of [window.BX, topWin?.BX].filter(Boolean)) {
			try {
				const id = typeof BXNS?.message === 'function' ? BXNS.message('USER_ID') : '';
				if (/^\d+$/.test(String(id || ''))) return _acceptCurrentBitrixUserId(id);
			} catch {}
			try {
				const id = BXNS?.Messenger?.Common?.getUserId?.() || BXNS?.user?.id;
				if (/^\d+$/.test(String(id || ''))) return _acceptCurrentBitrixUserId(id);
			} catch {}
		}
		return '';
	}

	async function _ensureCurrentBitrixUserId() {
		const current = _getCurrentBitrixUserId();
		if (current) return current;
		if (_dialogCurrentBitrixUserPromise) return _dialogCurrentBitrixUserPromise;
		_dialogCurrentBitrixUserPromise = _callBxRestPageWithTimeout('user.current', {}, 8000)
			.then(response => {
				const data = response?.data;
				const record = data?.result || data || {};
				const id = String(record?.ID ?? record?.id ?? '').trim();
				if (!/^\d+$/.test(id)) throw new Error('user.current did not return a numeric ID');
				return _acceptCurrentBitrixUserId(id);
			})
			.finally(() => { _dialogCurrentBitrixUserPromise = null; });
		return _dialogCurrentBitrixUserPromise;
	}

	function _buildTaskUrl(taskId) {
		const id = String(taskId || '').trim();
		if (!/^\d+$/.test(id)) return '';
		const userId = _getCurrentBitrixUserId();
		return userId ? `/company/personal/user/${userId}/tasks/task/view/${id}/?ta_sec=chat_tasks&ta_el=view_button` : '';
	}

	function _extractTaskMetaFromElement(el, fallbackTitle = '') {
		if (!el) return null;
		let taskUrl = '';
		try {
			taskUrl = Array.from(el.querySelectorAll?.('a[href]') || [])
				.map(a => a.getAttribute('href') || '')
				.map(_normalizeBitrixPath)
				.find(url => /\/tasks\/task\/view\/\d+/i.test(url)) || '';
		} catch {}

		const attrNames = ['taskId', 'taskid', 'task-id', 'data-task-id', 'entityId', 'entityid'];
		let taskId = _extractTaskIdFromTaskUrl(taskUrl);
		if (!taskId) {
			for (const name of attrNames) {
				const v = el.dataset?.[name] || el.getAttribute?.(name);
				if (/^\d+$/.test(String(v || ''))) {
					taskId = String(v);
					break;
				}
			}
		}
		if (!taskId) {
			const text = `${fallbackTitle || ''} ${el.textContent || ''}`;
			const m = /(?:задач[аиуы]?\s*|task\s*)?[#№]\s*(\d{2,})/i.exec(text);
			if (m) taskId = m[1];
		}
		if (!taskUrl && taskId) taskUrl = _buildTaskUrl(taskId);
		return taskUrl || taskId ? { taskId, taskUrl } : null;
	}

	function _extractTaskMetaFromDialogData(data) {
		if (!data || typeof data !== 'object') return null;
		const chat = data.chat && typeof data.chat === 'object' ? data.chat : data;
		const entityLink = chat.entity_link || chat.entityLink || data.entity_link || data.entityLink || null;
		const entityType = String(chat.entity_type || chat.entityType || data.entity_type || data.entityType || '').toUpperCase();
		const linkType = String(entityLink?.type || '').toUpperCase();
		let taskUrl = _normalizeBitrixPath(entityLink?.url || '');
		let taskId = _extractTaskIdFromTaskUrl(taskUrl);

		const entityId = String(chat.entity_id || chat.entityId || data.entity_id || data.entityId || '').trim();
		const linkedId = String(entityLink?.id || '').trim();
		if (!taskId && /^(TASKS|TASKS_TASK)$/.test(entityType) && /^\d+$/.test(entityId)) taskId = entityId;
		if (!taskId && linkType === 'TASKS' && /^\d+$/.test(linkedId)) taskId = linkedId;
		if (!taskUrl && taskId) taskUrl = _buildTaskUrl(taskId);

		return taskUrl || taskId ? { taskId, taskUrl } : null;
	}

	const _dialogTaskMetaCache = new Map();
	async function _resolveTaskMetaForDialog(dialogId) {
		const id = normId(dialogId);
		if (!id) return null;
		if (_dialogTaskMetaCache.has(id)) return _dialogTaskMetaCache.get(id);
		const promise = _callBxRestMethod('im.dialog.get', { DIALOG_ID: id })
			.then(_extractTaskMetaFromDialogData)
			.catch((e) => {
				warn('Не удалось получить связанную задачу для диалога', id, e?.message || e);
				return null;
			});
		_dialogTaskMetaCache.set(id, promise);
		const meta = await promise;
		if (meta) _dialogTaskMetaCache.set(id, meta);
		else _dialogTaskMetaCache.delete(id);
		return meta;
	}

function _rememberTaskMetaForDialogControlItem(item, meta) {
		if (!item || !meta) return false;
		let changed = false;
		if (meta.taskId && item.taskId !== String(meta.taskId)) {
			item.taskId = String(meta.taskId);
			changed = true;
		}
		if (meta.taskUrl && item.taskUrl !== meta.taskUrl) {
			item.taskUrl = meta.taskUrl;
			changed = true;
		}
		if (changed) _saveDialogControlItems();
		return changed;
	}

	function _extractDialogTitleFromDialogData(data) {
		const clean = (value) => String(value || '').replace(/\s+/g, ' ').trim();
		const seen = new Set();
		const read = (obj, depth = 0) => {
			if (!obj || typeof obj !== 'object' || depth > 3 || seen.has(obj)) return '';
			seen.add(obj);
			const keys = ['title', 'TITLE', 'name', 'NAME', 'dialogTitle', 'dialog_title', 'chatTitle', 'chat_title'];
			for (const key of keys) {
				const value = clean(obj[key]);
				if (value && !/^chat\d+$/i.test(value) && !/^\d+$/.test(value)) return value;
			}
			const nestedKeys = ['dialog', 'DIALOG', 'chat', 'CHAT', 'item', 'ITEM', 'result', 'RESULT', 'user', 'USER'];
			for (const key of nestedKeys) {
				const value = read(obj[key], depth + 1);
				if (value) return value;
			}
			return '';
		};
		return read(data);
	}

	function _extractTaskTitleFromData(data) {
		const clean = (value) => String(value || '').replace(/\s+/g, ' ').trim();
		const task = data?.task || data?.TASK || data?.result?.task || data?.RESULT?.TASK || data?.result?.TASK || data?.RESULT?.task || data;
		return clean(task?.title || task?.TITLE || task?.name || task?.NAME);
	}

	function _extractTaskRecordFromData(data) {
		return data?.task || data?.TASK || data?.result?.task || data?.RESULT?.TASK || data?.result?.TASK || data?.RESULT?.task || data || {};
	}

	function _rememberDialogTimeTaskEligibility(taskId, data) {
		const id = String(taskId || '').trim();
		if (!/^\d+$/.test(id)) return null;
		const task = _extractTaskRecordFromData(data);
		const taskChatDialogId = _rememberDialogTimeTaskChat(id, task?.CHAT_ID ?? task?.chatId ?? task?.chat?.id) ||
			_getDialogTimeTaskChatDialogId(id);
		const enabled = _readDialogTaskTimeTrackingFlag(task);
		if (enabled != null) _setDialogTimeTaskEligibility(id, enabled);
		const title = _extractTaskTitleFromData(data);
		if (title) _dialogTimeTaskTitles.set(id, title);
		let metaChanged = false;
		for (const meta of _getDialogRecentUniqueMeta()) {
			if (String(meta?.taskId || '') !== id) continue;
			let rowChanged = false;
			if (enabled != null && meta.timeTrackingEnabled !== enabled) {
				meta.timeTrackingEnabled = enabled;
				rowChanged = true;
			}
			if (title && meta.displayTitle !== title) {
				meta.displayTitle = title;
				meta.title = title.toLowerCase();
				rowChanged = true;
			}
			if (!rowChanged) continue;
			metaChanged = true;
			_markDialogRecentRepositoryDirty(meta.id);
		}
		if (metaChanged) {
			_dialogRecentDataRevision += 1;
			_scheduleDialogRecentCacheWrite(80);
			_notifyDialogRecentDataChanged();
		}
		if (title) {
			const dateKey = _getDialogTimeTodayKey();
			const visits = _readDialogTimeVisits(dateKey);
			let visitsChanged = false;
			visits.forEach(visit => {
				if (String(visit.taskId || '') !== id || visit.title === title) return;
				visit.title = title;
				visitsChanged = true;
			});
			if (visitsChanged) _writeDialogTimeVisits(visits, dateKey);
		}
		return enabled == null ? null : (enabled === true && !!taskChatDialogId);
	}

	function _ensureDialogTimeTaskEligibility(taskId, options = {}) {
		const id = String(taskId || '').trim();
		if (!/^\d+$/.test(id)) return Promise.resolve(false);
		const fresh = _getFreshDialogTimeTaskEligibility(id);
		if (fresh != null && options.force !== true) return Promise.resolve(fresh);
		if (_dialogTimeTaskEligibilityInFlight.has(id)) return _dialogTimeTaskEligibilityInFlight.get(id);
		const scope = _getDialogNativeSharedAuditScopeKey();
		const revision = _dialogTimeTaskRevisions.get(id) || 0;
		const request = _callBxRestMethod('tasks.task.get', {
			taskId: id,
			select: ['ID', 'TITLE', 'CHAT_ID', 'ALLOW_TIME_TRACKING']
		}, options).then(data => {
			if (scope !== _getDialogNativeSharedAuditScopeKey() || revision !== (_dialogTimeTaskRevisions.get(id) || 0)) return null;
			const enabled = _rememberDialogTimeTaskEligibility(id, data);
			return enabled == null ? null : enabled === true;
		})
			// Network/permission transport errors are not an explicit ALLOW_TIME_TRACKING=N.
			// Keep already collected work and retry instead of deleting it.
			.catch(() => null)
			.finally(() => {
				_dialogTimeTaskEligibilityInFlight.delete(id);
				_queueDialogTimeUiSync();
			});
		_dialogTimeTaskEligibilityInFlight.set(id, request);
		return request;
	}

	async function _resolveTaskTitleForDialogControlItem(item) {
		if (!item) return '';
		let taskId = item.taskId ? String(item.taskId) : '';
		if (!taskId) {
			const meta = await _resolveTaskMetaForDialog(item.id);
			if (meta) {
				_rememberTaskMetaForDialogControlItem(item, meta);
				taskId = meta.taskId ? String(meta.taskId) : '';
			}
		}
		if (!taskId) return '';
		try {
			const data = await _callBxRestMethod('tasks.task.get', { taskId });
			return _extractTaskTitleFromData(data);
		} catch (e) {
			try {
				const data = await _callBxRestMethod('tasks.task.get', { id: taskId });
				return _extractTaskTitleFromData(data);
			} catch (e2) {
				warn('Не удалось получить название задачи', taskId, e2?.message || e2 || e);
				return '';
			}
		}
	}

	function _openBitrixUrl(rawUrl) {
		const path = _normalizeBitrixPath(rawUrl);
		if (!path) return false;
		const topWin = _getSafeTopWindow();
		const candidates = [topWin, window].filter(Boolean);
		for (const win of candidates) {
			try {
				const sidePanel = win.BX?.SidePanel?.Instance;
				if (typeof sidePanel?.open === 'function') {
					sidePanel.open(path, { cacheable: false });
					return true;
				}
			} catch {}
		}
		try {
			(topWin || window).location.assign(new URL(path, window.location.origin).href);
			return true;
		} catch {}
		return false;
	}

	function _isTaskViewRouteNow() {
		if (/\/tasks\/task\/view\/\d+/i.test(`${window.location.pathname || ''}${window.location.search || ''}`)) return true;
		return !!_getActiveDialogControlScreenSnapshot().taskFrameInfo;
	}

	async function _openTaskForDialogControlItem(item) {
		if (!item) return false;
		let meta = item.taskUrl
			? { taskId: item.taskId || _extractTaskIdFromTaskUrl(item.taskUrl), taskUrl: _normalizeBitrixPath(item.taskUrl) }
			: _extractTaskMetaFromDialogData(item);
		if (!meta?.taskUrl && item.taskId) meta = { taskId: String(item.taskId), taskUrl: _buildTaskUrl(item.taskId) };
		if (!meta?.taskUrl) meta = await _resolveTaskMetaForDialog(item.id);
		if (!meta?.taskUrl) return false;
		_rememberTaskMetaForDialogControlItem(item, meta);
		const opened = _openBitrixUrl(meta.taskUrl);
		if (opened && meta.taskId) _rememberDialogTimeTaskVisit(meta.taskId, item.title || '', item.id || '', { takeover: true });
		return opened;
	}

	function _isDialogControlLiveStatusElement(element) {
		if (!element || element.hidden || element.getAttribute?.('aria-hidden') === 'true') return false;
		if (element.closest?.('[hidden],[aria-hidden="true"]')) return false;
		if (/(?:^|\s)(?:--|-|_)(?:hidden|invisible|disabled|inactive)(?:\s|$)/i.test(String(element.className || ''))) return false;
		try {
			const style = getComputedStyle(element);
			if (style.display === 'none' || style.visibility === 'hidden' || Number(style.opacity) === 0) return false;
		} catch {}
		return true;
	}

	function hasMentionMarker(el) {
		if (!el) return false;
		const selector = [
			'[class*="mention" i]',
			'[title*="упом" i]',
			'[title*="mention" i]',
			'[aria-label*="упом" i]',
			'[aria-label*="mention" i]',
			'[data-id*="mention" i]',
			'[data-testid*="mention" i]',
			'[data-test-id*="mention" i]'
		].join(',');
		try {
			const markers = [];
			if (el.matches?.(selector)) markers.push(el);
			markers.push(...Array.from(el.querySelectorAll?.(selector) || []));
			if (markers.length) return markers.some(_isDialogControlLiveStatusElement);
		} catch {}
		const own = [
			el.className,
			el.getAttribute?.('title'),
			el.getAttribute?.('aria-label'),
			el.dataset ? Object.values(el.dataset).join(' ') : ''
		].join(' ').toLowerCase();
		return /mention|упом/.test(own) && _isDialogControlLiveStatusElement(el);
	}

	let rankMap = new Map();
	let frozenSetSig = '';
	let tsMapOnce = null;
	let lastOrderSig = '';
	const currentSetSignature = (ids) => Array.from(new Set(ids)).sort().join('#');
	const currentOrderSignature = (ids) => ids.join('|');

	const RU_DAYS_SHORT = ['Вс','Пн','Вт','Ср','Чт','Пт','Сб'];
	const RU_MONTHS_GEN = ['января','февраля','марта','апреля','мая','июня','июля','августа','сентября','октября','ноября','декабря'];
	function dateKey(ts) {
	if (!ts || ts <= 0) return 'nodate';
	const d = new Date(ts);
	return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
}
	function formatGroupTitleFromTS(ts) {
	if (!ts || ts <= 0) return 'Без даты';
	const d = new Date(ts);
	const now = new Date();
	const d0 = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
	const dayStart = new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime();
	const diffDays = Math.round((dayStart - d0)/86400000);
	if (diffDays === 0) return 'сегодня';
	if (diffDays === -1) return 'вчера';
	const w = RU_DAYS_SHORT[d.getDay()];
	return `${w}, ${d.getDate()} ${RU_MONTHS_GEN[d.getMonth()]}`;
}
	function rebuildDateGroups(tsMap) {
	if (!IS_OL_FRAME) return;
	const container = findContainerOL();
	if (!container) return;
	container.querySelectorAll('.bx-messenger-recent-group').forEach(n => n.remove());
	const items = Array.from(container.querySelectorAll('.bx-messenger-cl-item'))
	.filter(el => el.style.display !== 'none');
	let lastKey = null;
	for (const el of items) {
	const id = (el.getAttribute('data-userid') || el.dataset.userid || '').toLowerCase();
	const ts = tsMap?.get?.(id)   -1;
	const key = dateKey(ts);
	if (key !== lastKey) {
	const div = document.createElement('div');
	div.className = 'bx-messenger-recent-group';
	const span = document.createElement('span');
	span.className = 'bx-messenger-recent-group-title';
	span.textContent = formatGroupTitleFromTS(ts);
	div.appendChild(span);
	container.insertBefore(div, el);
	lastKey = key;
}
}
}


