		if (host.classList.contains('--native-embedded')) {
			_setRzCursor('');
			return;
		}
		if (_rzActive) return;
		if (host.classList.contains('anit-hidden')) {
			_setRzCursor('');
			return;
		}
		const edges = _getEdges(ev);
		const overUI = !!ev.target.closest('button,input,select,textarea,a,[contenteditable],.controls-pop');
